import org.apache.logging.log4j.Logger;
import org.apache.logging.log4j.LogManager;
Logger log = LogManager.getLogger("loggerDex");
log.debug("in Inputing name step.");

import java.util.*;
import sailpoint.object.*;
import org.apache.logging.log4j.Logger;
import org.apache.logging.log4j.LogManager;
Logger log = LogManager.getLogger("loggerDex");
log.debug("Name = " + name);
log.debug("In Check Oracle Account Step");

Identity idenobject = context.getObject(Identity.class, name);

if (idenobject == null) {
    log.debug("No identity found for: " + name);
    return false;
}

String idenName = idenobject.getName();
 log.debug(idenName);


wfcontext.setVariable("identityName", idenName);

QueryOptions qo = new QueryOptions();
Filter f1 = Filter.eq("links.application.name", "Oracle Application");
Filter f2 = Filter.eq("name" , idenName);
qo.addFilter(f1);
qo.addFilter(f2);

int count = context.countObjects(Identity.class, qo);

boolean output;
if (count > 0){
output = true;
log.debug("Already has a Oracle Account");
}
else{
output = false;
log.debug("Creating PP");
}
return output;

import sailpoint.object.*;
import sailpoint.object.ProvisioningPlan;  
import sailpoint.object.ProvisioningPlan.AccountRequest;  
import sailpoint.object.ProvisioningPlan.AttributeRequest;   

import java.util.List;  
import java.util.ArrayList; 

import org.apache.logging.log4j.Logger;
import org.apache.logging.log4j.LogManager;

Logger log = LogManager.getLogger("loggerDex");
log.debug("Provisioning Started.");    

ProvisioningPlan plan = new ProvisioningPlan(); 

Identity identityObject = context.getObjectByName(Identity.class, identityName);  
log.debug("Employee... Create plan.");   

List accreqs = new ArrayList();      

AccountRequest acctReq = new AccountRequest();  
acctReq.setOperation(AccountRequest.Operation.Create);  
acctReq.setApplication("Oracle Application");  

accreqs.add(acctReq);  

plan.setAccountRequests(accreqs); 

plan.setIdentity(identityObject);  

log.debug("Plan Created");  

return plan;
